import { useMemo } from 'react';

import { useLastDataRefresh } from 'contexts';
import { formatDateToShortMonthYear } from 'utils/format';

const BREW_DAT_KPI_GROUP = 'market_share_official_total';
const ANAPLAN_KPI_GROUP = 'market_share';

export const useMarketShareGovernanceDates = () => {
  const { lastDataRefreshKpisDate } = useLastDataRefresh();

  return useMemo(() => {
    const brewDatDate = formatDateToShortMonthYear(
      lastDataRefreshKpisDate[BREW_DAT_KPI_GROUP] ?? undefined,
    );
    const anaplanDate = formatDateToShortMonthYear(
      lastDataRefreshKpisDate[ANAPLAN_KPI_GROUP] ?? undefined,
    );

    return {
      brewDatDate,
      anaplanDate,
      isGovernanceDatesReady: Boolean(brewDatDate && anaplanDate),
    };
  }, [lastDataRefreshKpisDate]);
};
